 1	method FindMax(a: array<int>) returns (i: int)
 2	    // Annotate this method with pre- and postconditions
 3	    // that ensure it behaves as described.
 4	    requires 0 < a.Length
 5	    ensures 0 <= i < a.Length
 6	    ensures forall k: int :: 0 <= k < a.Length ==> a[k] <= a[i] && k != 0
 7	{
 8	    // Fill in the body that calculates the INDEX of the maximum.
 9	    var j := 0;
10	    var max := a[0];
11	        i := 1;
12	    while i < a.Length
13	        invariant 1 <= i <= a.Length
14	        invariant forall k: int :: 0 <= k < i ==> max >= a[k]
15	        invariant 0 <= j < a.Length
16	        invariant a[j] == max
17	        decreases a.Length - i
18	    {
19	        if max < a[i] {
20	            max := a[i];
21	            j := i;
22	        }
23	        i := i + 1;
24	    }
25	
26	    i := j;
27	}

